mapper.select:
SELECT COUNT(1)
FROM biz_device_mgmt.alarm_history ah
INNER JOIN biz_device_base.device_base_info dbi ON ah.device_id = dbi.id
WHERE ah.tenant_id = #{tenantId}
  AND dbi.factory_id = #{factoryId}

      AND dbi.workshop_id = #{workshopId}


      AND dbi.device_code IN

          #{code}



      AND ah.start_ts >= #{startTime}


      AND ah.start_ts <= #{endTime}


      AND ah.is_active = #{isActive}


      AND ah.alarm_level IN

          #{level}

SELECT ah.id AS id, ah.tenant_id AS tenantId, ah.device_id AS deviceId, dbi.device_code AS deviceCode, dbi.device_name AS deviceName, dbi.device_type_name AS deviceTypeName, dbi.device_sub_type_name AS deviceSubTypeName, ah.alarm_code AS alarmCode, ah.alarm_text AS alarmText, ah.alarm_level AS alarmLevel, ah.start_ts AS startTs, ah.end_ts AS endTs, -- 持续时间：如果进行中，实时计算；否则使用存储的值 CASE WHEN ah.is_active = true THEN extract(epoch from now()) * 1000 - ah.start_ts ELSE ah.duration_ms END AS durationMs, ah.is_active AS isActive, ah.start_shift_date AS startShiftDate, ah.start_shift_code AS startShiftCode, ah.end_shift_date AS endShiftDate, ah.end_shift_code AS endShiftCode FROM biz_device_mgmt.alarm_history ah INNER JOIN biz_device_base.device_base_info dbi ON ah.device_id = dbi.id WHERE ah.tenant_id = #{tenantId} AND dbi.factory_id = #{factoryId}
AND dbi.workshop_id = #{workshopId}
AND dbi.device_code IN
#{code}
AND ah.start_ts >= #{startTime}
AND ah.start_ts <= #{endTime}
AND ah.is_active = #{isActive}
AND ah.alarm_level IN
#{level}
ORDER BY ah.start_ts DESC LIMIT #{limit} OFFSET #{offset}
